import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"📦 WMS 智能仓储与备件库存","description":"","frontmatter":{},"headers":[],"relativePath":"synergy/wms.md","filePath":"synergy/wms.md"}'),s={name:"synergy/wms.md"};function n(l,a,i,d,_,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="📦-wms-智能仓储与备件库存" tabindex="-1">📦 WMS 智能仓储与备件库存 <a class="header-anchor" href="#📦-wms-智能仓储与备件库存" aria-label="Permalink to &quot;📦 WMS 智能仓储与备件库存&quot;">​</a></h1><p><code>yudao-module-wms</code> 负责 MzMedia 中所有的物料、成品、传感器及备品备件仓储全生命周期管理。</p><hr><h2 id="_1-三级仓储空间拓扑" tabindex="-1">1. 三级仓储空间拓扑 <a class="header-anchor" href="#_1-三级仓储空间拓扑" aria-label="Permalink to &quot;1. 三级仓储空间拓扑&quot;">​</a></h2><ul><li><strong>物理仓库 (Warehouse)</strong>：如主厂区总仓、各车间线边仓、工程项目现场中转仓；</li><li><strong>功能库区 (Zone)</strong>：立库区、备品备件区、原材料区、半成品区、不合格品隔离区；</li><li><strong>货架库位 (Location)</strong>：精细化精确到排、列、层的具体物理货架库位编码。</li></ul><hr><h2 id="_2-备品备件与传感器单品条码追踪" tabindex="-1">2. 备品备件与传感器单品条码追踪 <a class="header-anchor" href="#_2-备品备件与传感器单品条码追踪" aria-label="Permalink to &quot;2. 备品备件与传感器单品条码追踪&quot;">​</a></h2><p>针对工业物联网工程中高价值的工控机、网关与精密传感器：</p><ul><li><strong>强制 SN 序列号管理</strong>：采购入库时一键打印防伪条码/二维码，扫码绑定单品唯一标识；</li><li><strong>工程领料锁定库存</strong>：当 PMS 工程立项或 MES 维修工单审批通过时，系统自动锁定对应的库位与备件，严防工程超发或重复领用；</li><li><strong>动态循环盘点与 FIFO</strong>：支持明盘（系统显示在库账面数）与暗盘（盲盘），出库时严格遵循先进先出（FIFO）规则，保证硬件保质期与批次可追溯。</li></ul>',9)])])}const u=e(s,[["render",n]]);export{m as __pageData,u as default};
